     1→export interface FogStroke {
     2→  x: number;
     3→  y: number;
     4→  radius: number;
     5→  mode: 'reveal' | 'fog';
     6→}
     7→
     8→export interface CanvasController {
     9→  loadImage(url: string): Promise<void>;
    10→  applyFogMask(base64: string): Promise<void>;
    11→  applyStroke(stroke: FogStroke): void;
    12→  drawBrushPreview(imgX: number, imgY: number, radius: number): void;
    13→  clearBrushPreview(): void;
    14→  getEventTarget(): HTMLCanvasElement;
    15→  getWrapper(): HTMLElement;
    16→  getImageSize(): { w: number; h: number };
    17→  clear(): void;
    18→}
    19→
    20→async function decompress(data: Uint8Array): Promise<Uint8Array> {
    21→  // Try zlib (deflate with header) first, then raw deflate
    22→  for (const fmt of ['deflate', 'deflate-raw'] as CompressionFormat[]) {
    23→    try {
    24→      const ds = new DecompressionStream(fmt);
    25→      const writer = ds.writable.getWriter();
    26→      const reader = ds.readable.getReader();
    27→      // Clone data to avoid detached buffer on retry
    28→      writer.write(data.slice());
    29→      writer.close();
    30→      const chunks: Uint8Array[] = [];
    31→      for (;;) {
    32→        const { done, value } = await reader.read();
    33→        if (done) break;
    34→        chunks.push(value);
    35→      }
    36→      const total = chunks.reduce((n, c) => n + c.length, 0);
    37→      const out = new Uint8Array(total);
    38→      let off = 0;
    39→      for (const c of chunks) { out.set(c, off); off += c.length; }
    40→      return out;
    41→    } catch {
    42→      // try next format
    43→    }
    44→  }
    45→  throw new Error('Failed to decompress fog mask');
    46→}
    47→
    48→export function initCanvas(container: HTMLElement, options?: { mode?: 'gm' | 'player' }): CanvasController {
    49→  const fogAlpha = options?.mode === 'player' ? 1.0 : 0.85;
    50→  const fogFill = `rgba(0,0,0,${fogAlpha})`;
    51→  const wrapper = document.createElement('div');
    52→  wrapper.style.cssText = 'position:relative;flex-shrink:0;';
    53→  container.appendChild(wrapper);
    54→
    55→  function makeCanvas(): HTMLCanvasElement {
    56→    const c = document.createElement('canvas');
    57→    c.style.cssText = 'position:absolute;top:0;left:0;width:100%;height:100%;';
    58→    wrapper.appendChild(c);
    59→    return c;
    60→  }
    61→
    62→  const mapCanvas = makeCanvas();
    63→  const fogCanvas = makeCanvas();
    64→  const previewCanvas = makeCanvas();
    65→  previewCanvas.style.pointerEvents = 'none';
    66→
    67→  if (options?.mode === 'player') {
    68→    fogCanvas.style.pointerEvents = 'none';
    69→  }
    70→
    71→  const mapCtx = mapCanvas.getContext('2d')!;
    72→  const fogCtx = fogCanvas.getContext('2d')!;
    73→  const previewCtx = previewCanvas.getContext('2d')!;
    74→
    75→  let imgW = 0;
    76→  let imgH = 0;
    77→
    78→  function sizeAll(w: number, h: number) {
    79→    imgW = w;
    80→    imgH = h;
    81→    for (const c of [mapCanvas, fogCanvas, previewCanvas]) {
    82→      c.width = w;
    83→      c.height = h;
    84→    }
    85→    // Set wrapper to image dimensions; viewport CSS transform handles visual scaling.
    86→    wrapper.style.width = `${w}px`;
    87→    wrapper.style.height = `${h}px`;
    88→  }
    89→
    90→  function fillFog() {
    91→    fogCtx.save();
    92→    fogCtx.globalCompositeOperation = 'source-over';
    93→    fogCtx.fillStyle = fogFill;
    94→    fogCtx.fillRect(0, 0, imgW, imgH);
    95→    fogCtx.restore();
    96→  }
    97→
    98→  return {
    99→    async loadImage(url: string) {
   100→      const img = new Image();
   101→      await new Promise<void>((res, rej) => {
   102→        img.onload = () => res();
   103→        img.onerror = () => rej(new Error(`Failed to load image: ${url}`));
   104→        img.src = url;
   105→      });
   106→      sizeAll(img.naturalWidth, img.naturalHeight);
   107→      mapCtx.clearRect(0, 0, imgW, imgH);
   108→      mapCtx.drawImage(img, 0, 0);
   109→      fogCtx.clearRect(0, 0, imgW, imgH);
   110→      fillFog();
   111→      previewCtx.clearRect(0, 0, imgW, imgH);
   112→    },
   113→
   114→    async applyFogMask(base64: string) {
   115→      const bin = atob(base64);
   116→      const bytes = new Uint8Array(bin.length);
   117→      for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
   118→      const view = new DataView(bytes.buffer);
   119→      let w = view.getUint32(0, false);
   120→      let h = view.getUint32(4, false);
   121→      if (w === 0 || h === 0) {
   122→        if (imgW === 0) return; // No image loaded yet
   123→        console.warn('Fog mask has 0x0 dimensions, falling back to loaded image dimensions', imgW, imgH);
   124→        w = imgW;
   125→        h = imgH;
   126→      }
   127→      const pixels = await decompress(bytes.slice(8));
   128→      if (imgW !== w || imgH !== h) sizeAll(w, h);
   129→      const id = fogCtx.createImageData(w, h);
   130→      for (let i = 0; i < pixels.length; i++) {
   131→        const v = pixels[i];
   132→        id.data[i * 4 + 0] = 0;
   133→        id.data[i * 4 + 1] = 0;
   134→        id.data[i * 4 + 2] = 0;
   135→        id.data[i * 4 + 3] = Math.round(v * fogAlpha);
   136→      }
   137→      fogCtx.putImageData(id, 0, 0);
   138→    },
   139→
   140→    applyStroke(stroke: FogStroke) {
   141→      if (imgW === 0) return;
   142→      fogCtx.save();
   143→      fogCtx.beginPath();
   144→      fogCtx.arc(stroke.x, stroke.y, stroke.radius, 0, Math.PI * 2);
   145→      if (stroke.mode === 'reveal') {
   146→        fogCtx.globalCompositeOperation = 'destination-out';
   147→        fogCtx.fillStyle = 'rgba(0,0,0,1)';
   148→      } else {
   149→        fogCtx.globalCompositeOperation = 'source-over';
   150→        fogCtx.fillStyle = fogFill;
   151→      }
   152→      fogCtx.fill();
   153→      fogCtx.restore();
   154→    },
   155→
   156→    drawBrushPreview(imgX: number, imgY: number, radius: number) {
   157→      if (imgW === 0) return;
   158→      previewCtx.clearRect(0, 0, imgW, imgH);
   159→      previewCtx.save();
   160→      previewCtx.strokeStyle = 'rgba(255,255,255,0.7)';
   161→      previewCtx.lineWidth = Math.max(1, 2 * (imgW / (wrapper.clientWidth || imgW)));
   162→      previewCtx.beginPath();
   163→      previewCtx.arc(imgX, imgY, radius, 0, Math.PI * 2);
   164→      previewCtx.stroke();
   165→      previewCtx.restore();
   166→    },
   167→
   168→    clearBrushPreview() {
   169→      if (imgW > 0) previewCtx.clearRect(0, 0, imgW, imgH);
   170→    },
   171→
   172→    getEventTarget() { return fogCanvas; },
   173→
   174→    getWrapper() { return wrapper; },
   175→
   176→    getImageSize() { return { w: imgW, h: imgH }; },
   177→
   178→    clear() {
   179→      mapCtx.clearRect(0, 0, imgW, imgH);
   180→      fogCtx.clearRect(0, 0, imgW, imgH);
   181→      previewCtx.clearRect(0, 0, imgW, imgH);
   182→    },
   183→  };
   184→}
