     1→import { connectGM } from './websocket';
     2→import { initCanvas } from './canvas';
     3→import { initTokenLayer } from './tokens';
     4→import { createViewport } from './viewport';
     5→import type { FogStroke } from './canvas';
     6→import * as api from './api';
     7→
     8→// --- URL params ---
     9→const fragment = new URLSearchParams(location.hash.slice(1));
    10→const adventureId = fragment.get('id') ?? '';
    11→const password = fragment.get('password') ?? '';
    12→
    13→if (!adventureId || !password) {
    14→  document.body.innerHTML = '<p style="padding:2rem">Missing adventure ID or password. <a href="/">Return home</a></p>';
    15→  throw new Error('Missing params');
    16→}
    17→
    18→// --- State ---
    19→let brushRadius = 50;
    20→let brushMode: 'reveal' | 'fog' = 'reveal';
    21→let activeImageId: string | null = null;
    22→let imageList: api.ImageRecord[] = [];
    23→let playerRoster: Array<{ tokenId: string; name: string; color: string; online: boolean }> = [];
    24→let inviteUrl = '';
    25→let presencePopover: HTMLElement | null = null;
    26→
    27→// --- DOM ---
    28→const adventureNameEl = document.getElementById('adventure-name')!;
    29→const connectionStatusEl = document.getElementById('connection-status')!;
    30→const playerPresenceEl = document.getElementById('player-presence')!;
    31→const brushSizeSlider = document.getElementById('brush-size') as HTMLInputElement;
    32→const brushSizeLabel = document.getElementById('brush-size-label')!;
    33→const modeRevealBtn = document.getElementById('mode-reveal')!;
    34→const modeFogBtn = document.getElementById('mode-fog')!;
    35→const undoBtn = document.getElementById('undo-btn') as HTMLButtonElement;
    36→const redoBtn = document.getElementById('redo-btn') as HTMLButtonElement;
    37→const mapPanelToggleBtn = document.getElementById('map-panel-toggle')!;
    38→const mapPanel = document.getElementById('map-panel')!;
    39→const gallery = document.getElementById('gallery')!;
    40→const uploadInput = document.getElementById('upload-input') as HTMLInputElement;
    41→const statusBar = document.getElementById('status-bar')!;
    42→const canvasArea = document.getElementById('canvas-area')!;
    43→
    44→// --- Canvas ---
    45→const canvasCtrl = initCanvas(canvasArea);
    46→
    47→// --- Viewport ---
    48→const viewport = createViewport();
    49→viewport.attach(canvasArea, canvasCtrl.getWrapper(), () => canvasCtrl.getImageSize());
    50→
    51→// --- Token layer (non-interactive for GM) ---
    52→const tokenCtrl = initTokenLayer(
    53→  canvasCtrl.getWrapper(),
    54→  () => canvasCtrl.getImageSize(),
    55→  (x, y) => viewport.screenToImage(x, y),
    56→  { interactive: false }
    57→);
    58→
    59→// --- WebSocket ---
    60→const ws = connectGM(adventureId, password);
    61→
    62→ws.on('connect', () => {
    63→  connectionStatusEl.className = 'status-dot connected';
    64→  statusBar.textContent = '';
    65→});
    66→ws.on('disconnect', () => {
    67→  connectionStatusEl.className = 'status-dot disconnected';
    68→  statusBar.textContent = '';
    69→});
    70→ws.on('error', (msg) => { console.error('WS error', msg); });
    71→
    72→ws.on('joined', async (msg) => {
    73→  const adv = msg.adventure as { id: string; name: string; activeImageId: string | null };
    74→  adventureNameEl.textContent = adv.name;
    75→
    76→  try {
    77→    const advData = await api.getAdventure(adventureId, password);
    78→    inviteUrl = `${location.origin}/player#link=${encodeURIComponent(advData.player_link)}`;
    79→  } catch {}
    80→
    81→  activeImageId = adv.activeImageId;
    82→  imageList = await api.listImages(adventureId, password);
    83→  renderGallery();
    84→
    85→  if (activeImageId) {
    86→    const img = imageList.find(i => i.id === activeImageId);
    87→    if (img) {
    88→      await canvasCtrl.loadImage(`/uploads/${img.filename}`);
    89→      viewport.resetView();
    90→      if (typeof msg.fogMask === 'string') {
    91→        await canvasCtrl.applyFogMask(msg.fogMask);
    92→      }
    93→    }
    94→  }
    95→
    96→  const tokens = msg.tokens as Array<{ id: string; name: string; color: string; x: number; y: number }>;
    97→  for (const token of tokens) {
    98→    tokenCtrl.addToken(token);
    99→  }
   100→
   101→  renderPresence(playerRoster);
   102→});
   103→
   104→ws.on('fog:stroke', (msg) => {
   105→  if (msg.imageId === activeImageId) {
   106→    canvasCtrl.applyStroke(msg.stroke as FogStroke);
   107→  }
   108→});
   109→
   110→ws.on('fog:stroke:batch', (msg) => {
   111→  if (msg.imageId === activeImageId) {
   112→    for (const stroke of msg.strokes as FogStroke[]) {
   113→      canvasCtrl.applyStroke(stroke);
   114→    }
   115→  }
   116→});
   117→
   118→ws.on('token:added', (msg) => {
   119→  const token = msg.token as { id: string; name: string; color: string; x: number; y: number };
   120→  tokenCtrl.addToken(token);
   121→});
   122→
   123→ws.on('token:moved', (msg) => {
   124→  tokenCtrl.moveToken(msg.tokenId as string, msg.x as number, msg.y as number);
   125→});
   126→
   127→ws.on('token:removed', (msg) => {
   128→  tokenCtrl.removeToken(msg.tokenId as string);
   129→});
   130→
   131→ws.on('player:roster', (msg) => {
   132→  playerRoster = msg.players as typeof playerRoster;
   133→  renderPresence(playerRoster);
   134→});
   135→
   136→ws.on('map:switched', async (msg) => {
   137→  activeImageId = msg.imageId as string;
   138→  resetUndoHistory();
   139→  imageList = await api.listImages(adventureId, password);
   140→  const img = imageList.find(i => i.id === activeImageId);
   141→  if (img) {
   142→    await canvasCtrl.loadImage(`/uploads/${img.filename}`);
   143→    viewport.resetView();
   144→    if (typeof msg.fogMask === 'string') {
   145→      await canvasCtrl.applyFogMask(msg.fogMask);
   146→    }
   147→  }
   148→  renderGallery();
   149→  tokenCtrl.render();
   150→});
   151→
   152→ws.on('fog:reset', (msg) => {
   153→  if (msg.imageId === activeImageId && typeof msg.fogMask === 'string') {
   154→    canvasCtrl.applyFogMask(msg.fogMask as string);
   155→  }
   156→});
   157→
   158→// --- Player presence ---
   159→function renderPresence(roster: Array<{ tokenId: string; name: string; color: string; online: boolean }>) {
   160→  const sorted = [...roster].sort((a, b) => {
   161→    if (a.online === b.online) return 0;
   162→    return a.online ? -1 : 1;
   163→  });
   164→
   165→  playerPresenceEl.replaceChildren();
   166→
   167→  const MAX_VISIBLE = 4;
   168→  const visible = sorted.length > MAX_VISIBLE ? sorted.slice(0, 3) : sorted;
   169→  const overflowCount = sorted.length > MAX_VISIBLE ? sorted.length - 3 : 0;
   170→
   171→  for (const player of visible) {
   172→    const avatar = document.createElement('div');
   173→    avatar.className = `presence-avatar ${player.online ? 'online' : 'offline'}`;
   174→    avatar.style.background = player.color;
   175→    avatar.textContent = player.name.charAt(0).toUpperCase();
   176→    avatar.title = player.name;
   177→    avatar.addEventListener('click', (e) => {
   178→      e.stopPropagation();
   179→      togglePresencePopover(sorted);
   180→    });
   181→    playerPresenceEl.appendChild(avatar);
   182→  }
   183→
   184→  if (overflowCount > 0) {
   185→    const overflowEl = document.createElement('div');
   186→    overflowEl.className = 'presence-avatar presence-overflow';
   187→    overflowEl.textContent = `+${overflowCount}`;
   188→    overflowEl.addEventListener('click', (e) => {
   189→      e.stopPropagation();
   190→      togglePresencePopover(sorted);
   191→    });
   192→    playerPresenceEl.appendChild(overflowEl);
   193→  }
   194→}
   195→
   196→function togglePresencePopover(roster: Array<{ tokenId: string; name: string; color: string; online: boolean }>) {
   197→  if (presencePopover) {
   198→    presencePopover.remove();
   199→    presencePopover = null;
   200→    return;
   201→  }
   202→
   203→  presencePopover = document.createElement('div');
   204→  presencePopover.className = 'presence-popover';
   205→
   206→  for (const player of roster) {
   207→    const row = document.createElement('div');
   208→    row.className = 'popover-player';
   209→
   210→    const dot = document.createElement('span');
   211→    dot.className = 'popover-player-dot';
   212→    dot.style.background = player.color;
   213→
   214→    const name = document.createElement('span');
   215→    name.className = 'popover-player-name';
   216→    name.textContent = player.name;
   217→
   218→    const status = document.createElement('span');
   219→    status.className = 'popover-player-status';
   220→    status.textContent = player.online ? 'online' : 'offline';
   221→
   222→    const actions = document.createElement('div');
   223→    actions.className = 'popover-player-actions';
   224→
   225→    const copyBtn = document.createElement('button');
   226→    copyBtn.className = 'popover-btn';
   227→    copyBtn.textContent = 'Copy link';
   228→    copyBtn.addEventListener('click', () => {
   229→      navigator.clipboard.writeText(inviteUrl).catch(() => {});
   230→    });
   231→
   232→    const removeBtn = document.createElement('button');
   233→    removeBtn.className = 'popover-btn danger';
   234→    removeBtn.textContent = '\u2715';
   235→    removeBtn.title = 'Remove player';
   236→    removeBtn.addEventListener('click', () => {
   237→      ws.send({ type: 'player:remove', tokenId: player.tokenId });
   238→      presencePopover?.remove();
   239→      presencePopover = null;
   240→    });
   241→
   242→    actions.appendChild(copyBtn);
   243→    actions.appendChild(removeBtn);
   244→    row.appendChild(dot);
   245→    row.appendChild(name);
   246→    row.appendChild(status);
   247→    row.appendChild(actions);
   248→    presencePopover.appendChild(row);
   249→  }
   250→
   251→  document.body.appendChild(presencePopover);
   252→
   253→  setTimeout(() => {
   254→    document.addEventListener('click', closePresencePopover, { once: true });
   255→  }, 0);
   256→}
   257→
   258→function closePresencePopover() {
   259→  presencePopover?.remove();
   260→  presencePopover = null;
   261→}
   262→
   263→// --- Map panel toggle ---
   264→mapPanelToggleBtn.addEventListener('click', () => {
   265→  const isOpen = mapPanel.hasAttribute('hidden');
   266→  if (isOpen) {
   267→    mapPanel.removeAttribute('hidden');
   268→  } else {
   269→    mapPanel.setAttribute('hidden', '');
   270→  }
   271→  mapPanelToggleBtn.classList.toggle('active', isOpen);
   272→});
   273→
   274→// --- Gallery ---
   275→function renderGallery() {
   276→  gallery.replaceChildren();
   277→  for (const img of imageList) {
   278→    const item = document.createElement('div');
   279→    item.className = 'gallery-item' + (img.id === activeImageId ? ' active' : '');
   280→
   281→    const thumb = document.createElement('img');
   282→    thumb.src = `/uploads/${img.filename}`;
   283→    thumb.alt = img.original_name;
   284→    thumb.title = img.original_name;
   285→    item.appendChild(thumb);
   286→
   287→    item.addEventListener('click', () => {
   288→      ws.send({ type: 'map:switch', imageId: img.id });
   289→    });
   290→    gallery.appendChild(item);
   291→  }
   292→}
   293→
   294→// --- Upload ---
   295→uploadInput.addEventListener('change', async () => {
   296→  const file = uploadInput.files?.[0];
   297→  if (!file) return;
   298→  try {
   299→    await api.uploadImage(adventureId, password, file);
   300→    imageList = await api.listImages(adventureId, password);
   301→    renderGallery();
   302→  } catch (e) {
   303→    console.error('Upload failed', e);
   304→  }
   305→  uploadInput.value = '';
   306→});
   307→
   308→// --- Brush controls ---
   309→brushSizeSlider.addEventListener('input', () => {
   310→  brushRadius = parseInt(brushSizeSlider.value, 10);
   311→  brushSizeLabel.textContent = `${brushRadius}`;
   312→});
   313→
   314→function setMode(mode: 'reveal' | 'fog') {
   315→  brushMode = mode;
   316→  modeRevealBtn.classList.toggle('active', mode === 'reveal');
   317→  modeFogBtn.classList.toggle('active', mode === 'fog');
   318→}
   319→
   320→modeRevealBtn.addEventListener('click', () => setMode('reveal'));
   321→modeFogBtn.addEventListener('click', () => setMode('fog'));
   322→
   323→// --- Undo/redo history ---
   324→const MAX_HISTORY = 50;
   325→let undoStack: FogStroke[][] = [];
   326→let redoStack: FogStroke[][] = [];
   327→let currentAction: FogStroke[] = [];
   328→
   329→function updateUndoRedoButtons() {
   330→  undoBtn.disabled = undoStack.length === 0;
   331→  redoBtn.disabled = redoStack.length === 0;
   332→}
   333→
   334→function sendUndo(strokes: FogStroke[]) {
   335→  ws.send({ type: 'fog:undo', strokes });
   336→}
   337→
   338→function performUndo() {
   339→  if (undoStack.length === 0) return;
   340→  const action = undoStack.pop()!;
   341→  redoStack.push(action);
   342→  sendUndo(undoStack.flat());
   343→  updateUndoRedoButtons();
   344→}
   345→
   346→function performRedo() {
   347→  if (redoStack.length === 0) return;
   348→  const action = redoStack.pop()!;
   349→  undoStack.push(action);
   350→  sendUndo(undoStack.flat());
   351→  updateUndoRedoButtons();
   352→}
   353→
   354→function resetUndoHistory() {
   355→  undoStack = [];
   356→  redoStack = [];
   357→  currentAction = [];
   358→  updateUndoRedoButtons();
   359→}
   360→
   361→undoBtn.addEventListener('click', performUndo);
   362→redoBtn.addEventListener('click', performRedo);
   363→
   364→document.addEventListener('keydown', (ev) => {
   365→  const ctrl = ev.ctrlKey || ev.metaKey;
   366→  if (!ctrl) return;
   367→  if (ev.key === 'z' || ev.key === 'Z') {
   368→    if (ev.shiftKey) {
   369→      ev.preventDefault();
   370→      performRedo();
   371→    } else {
   372→      ev.preventDefault();
   373→      performUndo();
   374→    }
   375→  } else if (ev.key === 'y' || ev.key === 'Y') {
   376→    ev.preventDefault();
   377→    performRedo();
   378→  }
   379→});
   380→
   381→// --- Brush interaction ---
   382→let isDrawing = false;
   383→const pending: FogStroke[] = [];
   384→let lastFlush = 0;
   385→const FLUSH_INTERVAL = 1000 / 60;
   386→
   387→function makeStroke(clientX: number, clientY: number): FogStroke {
   388→  const pos = viewport.screenToImage(clientX, clientY);
   389→  return { x: pos.x, y: pos.y, radius: brushRadius, mode: brushMode };
   390→}
   391→
   392→function flushPending() {
   393→  if (pending.length === 0) return;
   394→  if (pending.length === 1) {
   395→    ws.send({ type: 'fog:stroke', stroke: pending[0] });
   396→  } else {
   397→    ws.send({ type: 'fog:stroke:batch', strokes: pending.slice() });
   398→  }
   399→  pending.length = 0;
   400→  lastFlush = Date.now();
   401→}
   402→
   403→viewport.onInteractStart((ev: PointerEvent) => {
   404→  if (!activeImageId) return;
   405→  isDrawing = true;
   406→  currentAction = [];
   407→  const stroke = makeStroke(ev.clientX, ev.clientY);
   408→  canvasCtrl.applyStroke(stroke);
   409→  pending.push(stroke);
   410→  currentAction.push(stroke);
   411→  if (Date.now() - lastFlush >= FLUSH_INTERVAL) flushPending();
   412→});
   413→
   414→viewport.onPointerMove((ev: PointerEvent) => {
   415→  const pos = viewport.screenToImage(ev.clientX, ev.clientY);
   416→  canvasCtrl.drawBrushPreview(pos.x, pos.y, brushRadius);
   417→  if (!isDrawing) return;
   418→  const stroke = makeStroke(ev.clientX, ev.clientY);
   419→  canvasCtrl.applyStroke(stroke);
   420→  pending.push(stroke);
   421→  currentAction.push(stroke);
   422→  if (Date.now() - lastFlush >= FLUSH_INTERVAL) flushPending();
   423→});
   424→
   425→function finishAction() {
   426→  if (!isDrawing) return;
   427→  isDrawing = false;
   428→  flushPending();
   429→  if (currentAction.length > 0) {
   430→    undoStack.push(currentAction);
   431→    if (undoStack.length > MAX_HISTORY) undoStack.shift();
   432→    redoStack = [];
   433→    currentAction = [];
   434→    updateUndoRedoButtons();
   435→  }
   436→}
   437→
   438→viewport.onInteractEnd(() => {
   439→  finishAction();
   440→});
   441→
   442→viewport.onPointerLeave(() => {
   443→  canvasCtrl.clearBrushPreview();
   444→  finishAction();
   445→});
   446→

