     1→export interface Viewport {
     2→  readonly scale: number;
     3→  readonly panX: number;
     4→  readonly panY: number;
     5→  screenToImage(clientX: number, clientY: number): { x: number; y: number };
     6→  attach(
     7→    container: HTMLElement,
     8→    wrapper: HTMLElement,
     9→    getImageSize: () => { w: number; h: number }
    10→  ): void;
    11→  resetView(): void;
    12→  onChange(callback: () => void): void;
    13→  // Fires for all single-pointer moves (hover + drag). Caller checks own state.
    14→  onPointerMove(callback: (ev: PointerEvent) => void): void;
    15→  // Fires when grace period expires with 1 pointer — interact mode confirmed.
    16→  onInteractStart(callback: (ev: PointerEvent) => void): void;
    17→  // Fires when interact pointer lifts.
    18→  onInteractEnd(callback: () => void): void;
    19→  // Fires when pointer leaves the area.
    20→  onPointerLeave(callback: () => void): void;
    21→}
    22→
    23→export function createViewport(): Viewport {
    24→  let _scale = 1;
    25→  let _panX = 0;
    26→  let _panY = 0;
    27→  let _container: HTMLElement | null = null;
    28→  let _wrapper: HTMLElement | null = null;
    29→  let _getImageSize: (() => { w: number; h: number }) | null = null;
    30→
    31→  const changeCbs: Array<() => void> = [];
    32→  const moveCbs: Array<(ev: PointerEvent) => void> = [];
    33→  const startCbs: Array<(ev: PointerEvent) => void> = [];
    34→  const endCbs: Array<() => void> = [];
    35→  const leaveCbs: Array<() => void> = [];
    36→
    37→  function applyTransform() {
    38→    if (_wrapper) {
    39→      _wrapper.style.transform = `translate(${_panX}px,${_panY}px) scale(${_scale})`;
    40→    }
    41→    for (const cb of changeCbs) cb();
    42→  }
    43→
    44→  function computeBaseScale(): number {
    45→    if (!_container || !_getImageSize) return 1;
    46→    const { w, h } = _getImageSize();
    47→    if (w === 0 || h === 0) return 1;
    48→    const cw = _container.clientWidth || 800;
    49→    const ch = _container.clientHeight || 600;
    50→    return Math.min(cw / w, ch / h);
    51→  }
    52→
    53→  function clampScale(s: number): number {
    54→    const bs = computeBaseScale();
    55→    return Math.min(Math.max(bs, s), bs * 10);
    56→  }
    57→
    58→  function clampPan() {
    59→    if (!_container || !_getImageSize) return;
    60→    const { w, h } = _getImageSize();
    61→    const cw = _container.clientWidth;
    62→    const ch = _container.clientHeight;
    63→    const iw = w * _scale;
    64→    const ih = h * _scale;
    65→    _panX = Math.min(cw / 2, Math.max(cw / 2 - iw, _panX));
    66→    _panY = Math.min(ch / 2, Math.max(ch / 2 - ih, _panY));
    67→  }
    68→
    69→  // --- Pointer state ---
    70→  interface PPos { x: number; y: number }
    71→  const pointers = new Map<number, PPos>();
    72→  let graceTimer: ReturnType<typeof setTimeout> | null = null;
    73→  let gracePendingEv: PointerEvent | null = null;
    74→  let interacting = false;
    75→  let panActive = false;
    76→  let prevMidX = 0, prevMidY = 0, prevDist = 0;
    77→
    78→  function getMid() {
    79→    const pts = [...pointers.values()];
    80→    return { x: (pts[0].x + pts[1].x) / 2, y: (pts[0].y + pts[1].y) / 2 };
    81→  }
    82→
    83→  function getPinchDist() {
    84→    const pts = [...pointers.values()];
    85→    const dx = pts[0].x - pts[1].x;
    86→    const dy = pts[0].y - pts[1].y;
    87→    return Math.sqrt(dx * dx + dy * dy);
    88→  }
    89→
    90→  function cancelGrace() {
    91→    if (graceTimer !== null) { clearTimeout(graceTimer); graceTimer = null; }
    92→    gracePendingEv = null;
    93→  }
    94→
    95→  function commitInteract() {
    96→    interacting = true;
    97→    if (gracePendingEv) {
    98→      try { _container?.setPointerCapture(gracePendingEv.pointerId); } catch {}
    99→      const ev = gracePendingEv;
   100→      gracePendingEv = null;
   101→      for (const cb of startCbs) cb(ev);
   102→    }
   103→  }
   104→
   105→  function stopInteract() {
   106→    if (interacting) {
   107→      interacting = false;
   108→      for (const cb of endCbs) cb();
   109→    }
   110→  }
   111→
   112→  function initPanZoom() {
   113→    panActive = true;
   114→    const mid = getMid();
   115→    prevMidX = mid.x;
   116→    prevMidY = mid.y;
   117→    prevDist = getPinchDist();
   118→  }
   119→
   120→  function onDown(ev: PointerEvent) {
   121→    ev.preventDefault();
   122→    ev.stopPropagation();
   123→    pointers.set(ev.pointerId, { x: ev.clientX, y: ev.clientY });
   124→
   125→    if (pointers.size === 1) {
   126→      if (ev.button === 1) {
   127→        // Middle mouse — pan immediately
   128→        panActive = true;
   129→        prevMidX = ev.clientX;
   130→        prevMidY = ev.clientY;
   131→        try { _container?.setPointerCapture(ev.pointerId); } catch {}
   132→      } else {
   133→        // Start grace period
   134→        gracePendingEv = ev;
   135→        graceTimer = setTimeout(() => {
   136→          graceTimer = null;
   137→          if (pointers.size === 1 && !panActive) commitInteract();
   138→        }, 100);
   139→      }
   140→    } else if (pointers.size === 2) {
   141→      // Second finger — cancel grace/interact, start pan/zoom
   142→      cancelGrace();
   143→      stopInteract();
   144→      initPanZoom();
   145→      for (const [id] of pointers) {
   146→        try { _container?.setPointerCapture(id); } catch {}
   147→      }
   148→    }
   149→  }
   150→
   151→  function onMove(ev: PointerEvent) {
   152→    if (!pointers.has(ev.pointerId)) return;
   153→    ev.preventDefault();
   154→    ev.stopPropagation();
   155→    pointers.set(ev.pointerId, { x: ev.clientX, y: ev.clientY });
   156→
   157→    if (panActive) {
   158→      if (pointers.size >= 2) {
   159→        // Pinch + pan
   160→        const mid = getMid();
   161→        const dist = getPinchDist();
   162→        const dx = mid.x - prevMidX;
   163→        const dy = mid.y - prevMidY;
   164→        const factor = prevDist > 0 ? dist / prevDist : 1;
   165→        const newScale = clampScale(_scale * factor);
   166→        const af = newScale / _scale;
   167→        if (_container) {
   168→          const rect = _container.getBoundingClientRect();
   169→          const fx = prevMidX - rect.left;
   170→          const fy = prevMidY - rect.top;
   171→          _panX = fx - af * (fx - _panX) + dx;
   172→          _panY = fy - af * (fy - _panY) + dy;
   173→        }
   174→        _scale = newScale;
   175→        prevMidX = mid.x;
   176→        prevMidY = mid.y;
   177→        prevDist = dist;
   178→      } else {
   179→        // Middle mouse single-pointer pan
   180→        _panX += ev.clientX - prevMidX;
   181→        _panY += ev.clientY - prevMidY;
   182→        prevMidX = ev.clientX;
   183→        prevMidY = ev.clientY;
   184→      }
   185→      clampPan();
   186→      applyTransform();
   187→      return;
   188→    }
   189→
   190→    // Single-pointer interact or grace — fire move callbacks for brush preview / drawing
   191→    if (pointers.size === 1) {
   192→      for (const cb of moveCbs) cb(ev);
   193→    }
   194→  }
   195→
   196→  function onUp(ev: PointerEvent) {
   197→    ev.stopPropagation();
   198→    pointers.delete(ev.pointerId);
   199→    cancelGrace();
   200→    stopInteract();
   201→
   202→    if (pointers.size < 2) {
   203→      panActive = false;
   204→    }
   205→    if (pointers.size === 1 && !interacting) {
   206→      // Dropped from 2 to 1 — reinitialize for single-pointer pan if still panning
   207→      const pts = [...pointers.values()];
   208→      prevMidX = pts[0].x;
   209→      prevMidY = pts[0].y;
   210→    }
   211→  }
   212→
   213→  function onLeave(ev: PointerEvent) {
   214→    ev.stopPropagation();
   215→    const wasInteracting = interacting;
   216→    pointers.delete(ev.pointerId);
   217→    cancelGrace();
   218→    if (interacting) stopInteract();
   219→    if (pointers.size === 0) {
   220→      panActive = false;
   221→    }
   222→    if (wasInteracting || (!panActive && pointers.size === 0)) {
   223→      for (const cb of leaveCbs) cb();
   224→    }
   225→  }
   226→
   227→  return {
   228→    get scale() { return _scale; },
   229→    get panX() { return _panX; },
   230→    get panY() { return _panY; },
   231→
   232→    screenToImage(clientX, clientY) {
   233→      const rect = _container!.getBoundingClientRect();
   234→      return {
   235→        x: (clientX - rect.left - _panX) / _scale,
   236→        y: (clientY - rect.top - _panY) / _scale,
   237→      };
   238→    },
   239→
   240→    attach(container, wrapper, getImageSize) {
   241→      _container = container;
   242→      _wrapper = wrapper;
   243→      _getImageSize = getImageSize;
   244→      wrapper.style.transformOrigin = '0 0';
   245→      wrapper.style.willChange = 'transform';
   246→
   247→      container.addEventListener('pointerdown', onDown, { capture: true });
   248→      container.addEventListener('pointermove', onMove, { capture: true });
   249→      container.addEventListener('pointerup', onUp, { capture: true });
   250→      container.addEventListener('pointercancel', onUp, { capture: true });
   251→      container.addEventListener('pointerleave', onLeave, { capture: true });
   252→
   253→      container.addEventListener('wheel', (ev: WheelEvent) => {
   254→        ev.preventDefault();
   255→        const factor = ev.deltaY < 0 ? 1.1 : 1 / 1.1;
   256→        const rect = container.getBoundingClientRect();
   257→        const fx = ev.clientX - rect.left;
   258→        const fy = ev.clientY - rect.top;
   259→        const newScale = clampScale(_scale * factor);
   260→        const af = newScale / _scale;
   261→        _panX = fx - af * (fx - _panX);
   262→        _panY = fy - af * (fy - _panY);
   263→        _scale = newScale;
   264→        clampPan();
   265→        applyTransform();
   266→      }, { passive: false });
   267→    },
   268→
   269→    resetView() {
   270→      if (!_container || !_getImageSize) return;
   271→      const { w, h } = _getImageSize();
   272→      if (w === 0 || h === 0) return;
   273→      const cw = _container.clientWidth || 800;
   274→      const ch = _container.clientHeight || 600;
   275→      const bs = Math.min(cw / w, ch / h);
   276→      _scale = bs;
   277→      _panX = (cw - w * bs) / 2;
   278→      _panY = (ch - h * bs) / 2;
   279→      applyTransform();
   280→    },
   281→
   282→    onChange(cb) { changeCbs.push(cb); },
   283→    onPointerMove(cb) { moveCbs.push(cb); },
   284→    onInteractStart(cb) { startCbs.push(cb); },
   285→    onInteractEnd(cb) { endCbs.push(cb); },
   286→    onPointerLeave(cb) { leaveCbs.push(cb); },
   287→  };
   288→}
