    25→async function getFogMaskForImage(db: Database, imageId: string, uploadsDir?: string): Promise<FogMask> {
    26→  if (fogMaskCache.has(imageId)) return fogMaskCache.get(imageId)!;
    27→  const loaded = await loadFogMask(db, imageId);
    28→  if (loaded) {
    29→    fogMaskCache.set(imageId, loaded);
    30→    return loaded;
    31→  }
    32→  let image = getImage(db, imageId);
    33→  if (!image) throw new Error(`Image ${imageId} not found`);
    34→  if ((image.width === 0 || image.height === 0) && uploadsDir) {
    35→    repairImageDimensions(db, imageId, uploadsDir);
    36→    image = getImage(db, imageId) ?? image;
    37→  }
    38→  const mask = createMask(image.width, image.height);
    39→  fogMaskCache.set(imageId, mask);
    40→  return mask;
    41→}
    42→
    43→function scheduleSave(db: Database, imageId: string): void {
    44→  const existing = saveTimers.get(imageId);
    45→  if (existing) clearTimeout(existing);
    46→  const timer = setTimeout(async () => {
    47→    saveTimers.delete(imageId);
    48→    const mask = fogMaskCache.get(imageId);
    49→    if (mask) await saveFogMask(db, imageId, mask);
    50→  }, 500);
    51→  saveTimers.set(imageId, timer);
    52→}
    53→
    54→export async function flushAllFogCaches(db: Database): Promise<void> {
    55→  for (const timer of saveTimers.values()) clearTimeout(timer);
    56→  saveTimers.clear();
    57→  for (const [imageId, mask] of fogMaskCache) {
    58→    await saveFogMask(db, imageId, mask);
    59→  }
    60→}
    61→
    62→async function maskToBase64(mask: FogMask): Promise<string> {
    63→  const buf = await serializeMask(mask);
    64→  return buf.toString("base64");
    65→}
    66→
    67→// ---- Roster helpers ----
    68→
    69→function buildRoster(
    70→  db: Database,
    71→  adventureId: string
    72→): Array<{ tokenId: string; name: string; color: string; online: boolean }> {
    73→  const tokens = getTokensByAdventure(db, adventureId);
    74→  const conns = getConnectionsForAdventure(adventureId);
    75→  const onlineTokenIds = new Set(conns.map((c) => c.tokenId).filter(Boolean));
    76→  return tokens
    77→    .filter((t) => t.player_link !== null)
    78→    .map((t) => ({
    79→      tokenId: t.id,
    80→      name: t.name,
    81→      color: t.color,
    82→      online: onlineTokenIds.has(t.id),
    83→    }));
    84→}
    85→
    86→function sendRosterToGm(db: Database, adventureId: string): void {
    87→  const gmWs = getGmWsForAdventure(adventureId);
    88→  if (!gmWs) return;
    89→  gmWs.send(
    90→    serializeMessage({ type: "player:roster", players: buildRoster(db, adventureId) })
    91→  );
    92→}
    93→
    94→// ---- WebSocket upgrade (called from fetch handler) ----
    95→
    96→export function handleWsUpgrade(
    97→  req: Request,
    98→  db: Database,
    99→  server: Server
   100→): Response | undefined {
   101→  const url = new URL(req.url);
   102→  const adventureId = url.searchParams.get("adventureId");
   103→  const role = url.searchParams.get("role") as "gm" | "player" | null;
   104→  const password = url.searchParams.get("password");
   105→  const playerLink = url.searchParams.get("playerLink");
   106→  const playerName = url.searchParams.get("playerName");
   107→  const playerColor = url.searchParams.get("playerColor");
   108→
   109→  if (!adventureId || !role) {
   110→    return new Response("adventureId and role are required", { status: 400 });
   111→  }
   112→  if (role !== "gm" && role !== "player") {
   113→    return new Response("role must be gm or player", { status: 400 });
   114→  }
   115→
   116→  const adventure = getAdventure(db, adventureId);
   117→  if (!adventure) {
   118→    return new Response("Adventure not found", { status: 404 });
   119→  }
   120→
   121→  let tokenId: string | undefined;
   122→  let resolvedPlayerLink: string | undefined;
   123→  let tokenIsNew: boolean | undefined;
   124→
   125→  if (role === "gm") {
   126→    if (!password || password !== adventure.gm_password) {
   127→      return new Response("Invalid password", { status: 401 });
   128→    }
   129→  } else {
   130→    if (!playerLink) {
   131→      return new Response("playerLink is required for players", { status: 400 });
   132→    }
   133→    const linked = getAdventureByPlayerLink(db, playerLink);
   134→    if (!linked || linked.id !== adventureId) {
   135→      return new Response("Invalid player link", { status: 401 });
   136→    }
   137→    if (!playerName || !playerColor) {
   138→      return new Response("playerName and playerColor are required", { status: 400 });
   139→    }
   140→    // Identity key: adventure invite link + player name.
   141→    // Same bookmark URL (same name) → same token. Different name → different token.
   142→    const playerIdentity = `${playerLink}|${playerName}`;
   143→    const { token, isNew } = findOrCreateToken(db, {
   144→      adventureId,
   145→      playerLink: playerIdentity,
   146→      name: playerName,
   147→      color: playerColor,
   148→    });
   149→    tokenId = token.id;
   150→    resolvedPlayerLink = playerLink;
   151→    tokenIsNew = isNew;
   152→  }
   153→
   154→  const wsData: WsData = {
   155→    adventureId,
   156→    role,
   157→    playerName: playerName ?? undefined,
   158→    playerColor: playerColor ?? undefined,
   159→    tokenId,
   160→    playerLink: resolvedPlayerLink,
   161→    tokenIsNew,
   162→  };
   163→
   164→  const upgraded = server.upgrade(req, { data: wsData });
   165→  if (!upgraded) {
   166→    return new Response("WebSocket upgrade failed", { status: 500 });
   167→  }
   168→  // Return undefined so Bun completes the WebSocket handshake
   169→  return undefined;
   170→}
   171→
   172→// ---- WebSocket handlers ----
   173→
   174→export function createWsHandlers(db: Database, uploadsDir?: string) {
   175→  return {
   176→    async open(ws: ServerWebSocket<WsData>) {
   177→      const { adventureId, role, playerName, playerColor, tokenId, playerLink, tokenIsNew } = ws.data;
   178→      registerConnection(ws, { adventureId, role, playerName, playerColor, tokenId, playerLink });
   179→
   180→      const adventure = getAdventure(db, adventureId)!;
   181→      const tokens = getTokensByAdventure(db, adventureId);
   182→
   183→      let fogMask: string | null = null;
   184→      if (adventure.active_image_id) {
   185→        try {
   186→          const mask = await getFogMaskForImage(db, adventure.active_image_id, uploadsDir);
   187→          fogMask = await maskToBase64(mask);
   188→        } catch {
   189→          fogMask = null;
   190→        }
   191→      }
   192→
   193→      ws.send(
   194→        serializeMessage({
   195→          type: "joined",
   196→          adventure: {
   197→            id: adventure.id,
   198→            name: adventure.name,
   199→            activeImageId: adventure.active_image_id,
   200→          },
   201→          tokens,
   202→          fogMask,
   203→          yourTokenId: tokenId,
   204→        })
   205→      );
   206→
   207→      if (role === "gm") {
   208→        // Send roster immediately so GM sees current player status
   209→        ws.send(
   210→          serializeMessage({ type: "player:roster", players: buildRoster(db, adventureId) })
   211→        );
   212→      }
   213→
   214→      if (role === "player" && playerName && playerColor) {
   215→        ws.publish(
   216→          `adventure:${adventureId}`,
   217→          serializeMessage({ type: "player:joined", playerName, playerColor })
   218→        );
   219→
   220→        if (tokenId && tokenIsNew) {
   221→          // Newly created token — tell other clients to add it
   222→          const newToken = tokens.find((t) => t.id === tokenId);
   223→          if (newToken) {
   224→            ws.publish(
   225→              `adventure:${adventureId}`,
   226→              serializeMessage({ type: "token:added", token: newToken })
   227→            );
   228→          }
   229→        }
   230→        // If reconnecting (tokenIsNew === false), token is already in other clients' state
   231→
   232→        // Update GM roster to show this player as online
   233→        sendRosterToGm(db, adventureId);
   234→      }
   235→    },
   236→
   237→    async message(ws: ServerWebSocket<WsData>, raw: string | Buffer) {
   238→      const conn = getConnection(ws);
   239→      if (!conn) return;
   240→
   241→      const msg = parseMessage(typeof raw === "string" ? raw : raw.toString());
   242→      if (!msg) {
   243→        ws.send(serializeMessage({ type: "error", message: "Invalid message format" }));
   244→        return;
   245→      }
   246→
   247→      const { adventureId } = conn;
   248→      const topic = `adventure:${adventureId}`;
   249→
   250→      switch (msg.type) {
   251→        case "join": {
   252→          ws.send(serializeMessage({ type: "error", message: "Already joined" }));
   253→          break;
   254→        }
   255→
   256→        case "fog:stroke": {
   257→          if (conn.role !== "gm") {
   258→            ws.send(serializeMessage({ type: "error", message: "Only GM can send fog strokes" }));
   259→            break;
   260→          }
   261→          const adv = getAdventure(db, adventureId);
   262→          if (!adv?.active_image_id) {
   263→            ws.send(serializeMessage({ type: "error", message: "No active image" }));
   264→            break;
   265→          }
   266→          const imageId = adv.active_image_id;
   267→          const mask = await getFogMaskForImage(db, imageId, uploadsDir);
   268→          applyStroke(mask, msg.stroke);
   269→          scheduleSave(db, imageId);
   270→          ws.publish(topic, serializeMessage({ type: "fog:stroke", stroke: msg.stroke, imageId }));
   271→          break;
   272→        }
   273→
   274→        case "fog:stroke:batch": {
   275→          if (conn.role !== "gm") {
   276→            ws.send(serializeMessage({ type: "error", message: "Only GM can send fog strokes" }));
   277→            break;
   278→          }
   279→          const adv = getAdventure(db, adventureId);
   280→          if (!adv?.active_image_id) {
   281→            ws.send(serializeMessage({ type: "error", message: "No active image" }));
   282→            break;
   283→          }
   284→          const imageId = adv.active_image_id;
   285→          const mask = await getFogMaskForImage(db, imageId, uploadsDir);
   286→          applyStrokes(mask, msg.strokes);
   287→          scheduleSave(db, imageId);
   288→          ws.publish(topic, serializeMessage({ type: "fog:stroke:batch", strokes: msg.strokes, imageId }));
   289→          break;
   290→        }
   291→
   292→        case "token:move": {
   293→          if (!conn.tokenId || conn.tokenId !== msg.tokenId) {
   294→            ws.send(serializeMessage({ type: "error", message: "You do not own this token" }));
   295→            break;
   296→          }
   297→          updateTokenPosition(db, msg.tokenId, msg.x, msg.y);
   298→          const moved = serializeMessage({
   299→            type: "token:moved",
   300→            tokenId: msg.tokenId,
   301→            x: msg.x,
   302→            y: msg.y,
   303→          });
   304→          ws.send(moved);
   305→          ws.publish(topic, moved);
   306→          break;
   307→        }
   308→
   309→        case "map:switch": {
   310→          if (conn.role !== "gm") {
   311→            ws.send(serializeMessage({ type: "error", message: "Only GM can switch maps" }));
   312→            break;
   313→          }
   314→          try {
   315→            setActiveImage(db, adventureId, msg.imageId);
   316→          } catch {
   317→            ws.send(serializeMessage({ type: "error", message: "Invalid image" }));
   318→            break;
   319→          }
   320→          let fogMask: string | null = null;
   321→          try {
   322→            const mask = await getFogMaskForImage(db, msg.imageId, uploadsDir);
   323→            fogMask = await maskToBase64(mask);
   324→          } catch {
   325→            fogMask = null;
   326→          }
   327→          const switched = serializeMessage({
   328→            type: "map:switched",
   329→            imageId: msg.imageId,
   330→            fogMask,
   331→          });
   332→          ws.send(switched);
   333→          ws.publish(topic, switched);
   334→          break;
   335→        }
   336→
   337→        case "player:remove": {
   338→          if (conn.role !== "gm") {
   339→            ws.send(serializeMessage({ type: "error", message: "Only GM can remove players" }));
   340→            break;
   341→          }
   342→          const tokens = getTokensByAdventure(db, adventureId);
   343→          const target = tokens.find((t) => t.id === msg.tokenId);
   344→          if (!target) {
   345→            ws.send(serializeMessage({ type: "error", message: "Token not found" }));
   346→            break;
   347→          }
   348→
   349→          // Notify the player they've been removed (if connected), then close their WS
   350→          const playerWs = getWsForToken(adventureId, msg.tokenId);
   351→          if (playerWs) {
   352→            playerWs.send(serializeMessage({ type: "player:removed" }));
   353→            playerWs.close(4000, "removed");
   354→          }
   355→
   356→          deleteToken(db, msg.tokenId);
   357→          ws.publish(topic, serializeMessage({ type: "token:removed", tokenId: msg.tokenId }));
   358→
   359→          // Send updated roster after deletion
   360→          sendRosterToGm(db, adventureId);
   361→          break;
   362→        }
   363→
   364→        case "fog:undo": {
   365→          if (conn.role !== "gm") {
   366→            ws.send(serializeMessage({ type: "error", message: "Only GM can undo fog strokes" }));
   367→            break;
   368→          }
   369→          const adv = getAdventure(db, adventureId);
   370→          if (!adv?.active_image_id) {
   371→            ws.send(serializeMessage({ type: "error", message: "No active image" }));
   372→            break;
   373→          }
   374→          const imageId = adv.active_image_id;
   375→          let image = getImage(db, imageId);
   376→          if (!image) {
   377→            ws.send(serializeMessage({ type: "error", message: "Image not found" }));
   378→            break;
   379→          }
   380→          if ((image.width === 0 || image.height === 0) && uploadsDir) {
   381→            repairImageDimensions(db, imageId, uploadsDir);
   382→            image = getImage(db, imageId) ?? image;
   383→          }
   384→          const freshMask = createMask(image.width, image.height);
   385→          applyStrokes(freshMask, msg.strokes);
   386→          fogMaskCache.set(imageId, freshMask);
   387→          scheduleSave(db, imageId);
   388→          const fogMaskBase64 = await maskToBase64(freshMask);
   389→          const resetMsg = serializeMessage({ type: "fog:reset", imageId, fogMask: fogMaskBase64 });
   390→          ws.send(resetMsg);
   391→          ws.publish(topic, resetMsg);
   392→          break;
   393→        }
   394→
   395→        case "ping": {
   396→          ws.send(serializeMessage({ type: "pong" }));
   397→          break;
   398→        }
   399→
   400→        default: {
   401→          ws.send(serializeMessage({ type: "error", message: "Unknown message type" }));
   402→        }
   403→      }
   404→    },
   405→
   406→    close(ws: ServerWebSocket<WsData>) {
   407→      const info = unregisterConnection(ws);
   408→      if (!info) return;
   409→
   410→      if (info.role === "gm") {
   411→        // Flush any pending fog saves immediately on GM disconnect
   412→        for (const [imageId, timer] of saveTimers) {
   413→          clearTimeout(timer);
   414→          saveTimers.delete(imageId);
   415→          const mask = fogMaskCache.get(imageId);
   416→          if (mask) saveFogMask(db, imageId, mask).catch(() => {});
   417→        }
   418→      }
   419→
   420→      const topic = `adventure:${info.adventureId}`;
   421→
   422→      // Token persists on disconnect — do NOT delete it
   423→      if (info.playerName) {
   424→        ws.publish(topic, serializeMessage({ type: "player:left", playerName: info.playerName }));
   425→      }
   426→
   427→      if (info.role === "player") {
   428→        // Update GM roster to show this player as offline
   429→        sendRosterToGm(db, info.adventureId);
   430→      }
   431→    },
   432→  };
   433→}
