   271→          break;
   272→        }
   273→
   274→        case "fog:stroke:batch": {
   275→          if (conn.role !== "gm") {
   276→            ws.send(serializeMessage({ type: "error", message: "Only GM can send fog strokes" }));
   277→            break;
   278→          }
   279→          const adv = getAdventure(db, adventureId);
   280→          if (!adv?.active_image_id) {
