   282→            break;
   283→          }
   284→          const imageId = adv.active_image_id;
   285→          const mask = await getFogMaskForImage(db, imageId, uploadsDir);
   286→          applyStrokes(mask, msg.strokes);
   287→          scheduleSave(db, imageId);
   288→          ws.publish(topic, serializeMessage({ type: "fog:stroke:batch", strokes: msg.strokes, imageId }));
   289→          break;
   290→        }
   291→
   292→        case "token:move": {
