   397→          break;
   398→        }
   399→
   400→        default: {
   401→          ws.send(serializeMessage({ type: "error", message: "Unknown message type" }));
   402→        }
   403→      }
   404→    },
   405→
   406→    close(ws: ServerWebSocket<WsData>) {
   407→      const info = unregisterConnection(ws);
   408→      if (!info) return;
   409→
   410→      if (info.role === "gm") {
   411→        // Flush any pending fog saves immediately on GM disconnect
   412→        for (const [imageId, timer] of saveTimers) {
   413→          clearTimeout(timer);
   414→          saveTimers.delete(imageId);
