   421→
   422→      // Token persists on disconnect — do NOT delete it
   423→      if (info.playerName) {
   424→        ws.publish(topic, serializeMessage({ type: "player:left", playerName: info.playerName }));
   425→      }
   426→
   427→      if (info.role === "player") {
