    onPointerMove(cb) { moveCbs.push(cb); },
    onInteractStart(cb) { startCbs.push(cb); },
    onInteractEnd(cb) { endCbs.push(cb); },
    onPointerLeave(cb) { leaveCbs.push(cb); },
  };
}

