    longPressTimer = setTimeout(() => {
      longPressTimer = null;
      const now = Date.now();
      if (now - lastPingTime >= PING_RATE_LIMIT) {
        lastPingTime = now;
        const pos = viewport.screenToImage(longPressStartPos!.x, longPressStartPos!.y);
        ws.send({ type: 'ping:map', x: pos.x, y: pos.y, color: playerColor });
      }
    }, LONG_PRESS_DELAY);
